10: static bool validate_utf8(const char *b, size_t length) {
11:   const unsigned char *bytes = (const unsigned char *)b;
12:   for (size_t index = 0;;) {
13:     // Inspect only complete words; memcpy permits unaligned input without
14:     // violating aliasing or alignment rules.
15:     while (length - index >= sizeof(uint64_t)) {
16:       uint64_t word;
17:       std::memcpy(&word, bytes + index, sizeof(word));
18:       if ((word & UINT64_C(0x8080808080808080)) == 0) {
19:         index += sizeof(word);
20:         continue;
21:       }
22: 
23:       // Find the first non-ASCII byte in this bounded word, then let the
24:       // existing scalar decoder validate it and the following bytes.
25:       const size_t block_end = index + sizeof(word);
26:       while (index < block_end && bytes[index] < 0x80) {
27:         ++index;
28:       }
29:       break;
30:     }
31: 
32:     if (index == length) {
33:       return true;
34:     }
35:     unsigned char byte1 = bytes[index++];
36:     if (byte1 < 0x80) {
37:       continue;
38:     }
39:     if (byte1 < 0xE0) {
40:       // Two-byte form.
41:       if (index == length) {
42:         return false;
43:       }
44:       if (byte1 < 0xC2 || (bytes[index++] & 0xC0) != 0x80) {
45:         return false;
46:       }
47:     } else if (byte1 < 0xF0) {
48:       // Three-byte form.
49:       if (index + 1 >= length) {
50:         return false;
51:       }
52:       unsigned char byte2 = bytes[index++];
53:       if ((byte2 & 0xC0) != 0x80
54:           // Overlong? 5 most significant bits must not all be zero.
55:           || (byte1 == 0xE0 && byte2 < 0xA0)
56:           // Check for illegal surrogate codepoints.
57:           || (byte1 == 0xED && 0xA0 <= byte2)
58:           // Third byte trailing-byte test.
59:           || (bytes[index++] & 0xC0) != 0x80) {
60:         return false;
61:       }
62:     } else {
63:       // Four-byte form.
64:       if (index + 2 >= length) {
65:         return false;
66:       }
67:       int byte2 = bytes[index++];
68:       if ((byte2 & 0xC0) != 0x80
69:           // Check that 1 <= plane <= 16. Tricky optimized form of:
70:           // if (byte1 > (byte) 0xF4
71:           //     || byte1 == (byte) 0xF0 && byte2 < (byte) 0x90
72:           //     || byte1 == (byte) 0xF4 && byte2 > (byte) 0x8F)
73:           || (byte1 > 0xF4 || (byte1 == 0xF0 && byte2 < 0x90) || (byte1 == 0xF4 && byte2 > 0x8F))
74:           // Third byte trailing-byte test
75:           || (bytes[index++] & 0xC0) != 0x80
76:           // Fourth byte trailing-byte test
77:           || (bytes[index++] & 0xC0) != 0x80) {
78:         return false;
79:       }
80:     }
81:   }
82: }
