static inline bool is_continuation(unsigned char byte) {
  return (byte & 0xC0u) == 0x80u;
}

static inline bool valid_special_second(unsigned char lead, unsigned char second) {
  if (lead == 0xE0u && second < 0xA0u) return false;
  if (lead == 0xEDu && second > 0x9Fu) return false;
  if (lead == 0xF0u && second < 0x90u) return false;
  if (lead == 0xF4u && second > 0x8Fu) return false;
  return true;
}

static bool validate_scalar(const unsigned char *bytes, size_t index, size_t length) {
  while (index < length) {
    const unsigned char lead = bytes[index++];
    if (lead < 0x80u) continue;

    if (lead < 0xE0u) {
      if (lead < 0xC2u || length - index < 1u) return false;
      const unsigned char second = bytes[index++];
      if (!is_continuation(second)) return false;
    } else if (lead < 0xF0u) {
      if (length - index < 2u) return false;
      const unsigned char second = bytes[index++];
      const unsigned char third = bytes[index++];
      if (!is_continuation(second) || !valid_special_second(lead, second) ||
          !is_continuation(third)) return false;
    } else {
      if (lead > 0xF4u || length - index < 3u) return false;
      const unsigned char second = bytes[index++];
      const unsigned char third = bytes[index++];
      const unsigned char fourth = bytes[index++];
      if (!is_continuation(second) || !valid_special_second(lead, second) ||
          !is_continuation(third) || !is_continuation(fourth)) return false;
    }
  }
  return true;
}

