  const __m128i zero = _mm_setzero_si128();
  const __m128i ones = _mm_set1_epi8(-1);
  const __m128i continuation_mask = _mm_set1_epi8(-64);
  const __m128i continuation_value = _mm_set1_epi8(-128);
  const __m128i c1 = _mm_set1_epi8(-63);
  const __m128i e0 = _mm_set1_epi8(-32);
  const __m128i df = _mm_set1_epi8(-33);
  const __m128i ef = _mm_set1_epi8(-17);
  const __m128i f0 = _mm_set1_epi8(-16);
  const __m128i f5 = _mm_set1_epi8(-11);

  while (length - index >= 16u) {
    const __m128i block = _mm_loadu_si128(
        reinterpret_cast<const __m128i *>(bytes + index));
    const __m128i high = _mm_cmplt_epi8(block, zero);
    const __m128i ascii = _mm_andnot_si128(high, ones);
    const __m128i continuation = _mm_cmpeq_epi8(
        _mm_and_si128(block, continuation_mask), continuation_value);
    const __m128i two = _mm_and_si128(_mm_cmpgt_epi8(block, c1),
                                      _mm_cmpgt_epi8(e0, block));
    const __m128i three = _mm_and_si128(_mm_cmpgt_epi8(block, df),
