    const unsigned two_bits =
        static_cast<unsigned>(_mm_movemask_epi8(two)) & 0xFFFFu;
    const unsigned three_bits =
        static_cast<unsigned>(_mm_movemask_epi8(three)) & 0xFFFFu;
    const unsigned four_bits =
        static_cast<unsigned>(_mm_movemask_epi8(four)) & 0xFFFFu;
    unsigned expected = (((two_bits | three_bits | four_bits) << 1) |
