    if (length - index < carry) return false;
    if (!valid_special_second(bytes[index - 1u], bytes[index])) return false;
    for (unsigned i = 0; i < carry; ++i) {
      if (!is_continuation(bytes[index])) return false;
      ++index;
    }
  }
  return validate_scalar(bytes, index, length);
#else
  return validate_scalar(bytes, 0u, length);
#endif
}

